import React, { useEffect, useMemo } from "react";
import { Box, Button, IconButton, Typography, useMediaQuery, useTheme } from "@mui/material";
import WhatsAppIcon from "@mui/icons-material/WhatsApp";
import CloseIcon from "@mui/icons-material/Close";
import { useProfilesStore } from "@/store";
import { ensureMyProfileLoaded } from "@/lib/profile-cache";
import { storage, WA_BANNER_DISMISSED_KEY } from "@/utils/storage";
import { getWhatsAppGroup, openWhatsAppGroup, WhatsAppGroupConfig } from "@/constants/StaticData";

export { WA_BANNER_DISMISSED_KEY };

export const WhatsAppBanner: React.FC = () => {
  const profile = useProfilesStore((s) => s.profileState.data);
  const [dismissed, setDismissed] = React.useState<boolean>(
    () => storage.getString(WA_BANNER_DISMISSED_KEY) === '1'
  );
  const theme = useTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down('sm'), { noSsr: true });

  const waGroup: WhatsAppGroupConfig | undefined = useMemo(
    () => (profile?.id ? getWhatsAppGroup(profile.firstJnvId, profile.location) : undefined),
    [profile?.id, profile?.firstJnvId, profile?.location]
  );

  const handleJoin = () => { if (waGroup) openWhatsAppGroup(waGroup); };

  useEffect(() => {
    if (dismissed) return;
    void ensureMyProfileLoaded();
  }, [dismissed]);

  if (!waGroup || dismissed || !isMobile) return null;

  return (
    <Box sx={{
      backgroundColor: '#dcf8c6',
      borderRadius: 2,
      p: 2,
      pb: 3.5,
      mb: 2,
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'space-between',
      flexWrap: 'wrap',
      gap: 1,
      position: 'relative',
    }}>
      <Typography variant="body2" sx={{ color: 'text.primary', fontWeight: 500, flexGrow: 1 }}>
        Join the <b style={{ color: '#d32f2f' }}>{waGroup.label}</b> WhatsApp Group!
      </Typography>
      <Button
        variant="contained"
        size="small"
        startIcon={<WhatsAppIcon />}
        onClick={handleJoin}
        sx={{
          backgroundColor: '#25D366',
          '&:hover': { backgroundColor: '#1ebe57' },
          textTransform: 'none',
          fontWeight: 600,
        }}
      >
        Join Group
      </Button>
      <IconButton
        size="small"
        onClick={() => {
          storage.setString(WA_BANNER_DISMISSED_KEY, '1');
          setDismissed(true);
        }}
        sx={{ position: 'absolute', right: 4, bottom: 4, color: 'text.secondary' }}
      >
        <CloseIcon sx={{ fontSize: '1.1rem' }} />
      </IconButton>
    </Box>
  );
};
