import React from 'react';
import { createFileRoute } from '@tanstack/react-router';
import { Home } from '@/pages/home/Home';
import { Landing } from '@/pages/home/Landing';
import { IsTokenValid } from '@/utils/token';

/**
 * "/" serves two different pages: signed-out visitors get the public landing page (app name +
 * what the app is for), members get the search home.
 *
 * The stored token is read directly rather than through the router context: that context is
 * captured when the match loads and does not track sign-in/sign-out, so a signed-in member
 * would otherwise be shown the landing page.
 */
function RootIndex() {
    const [signedIn, setSignedIn] = React.useState<boolean>(IsTokenValid);

    React.useEffect(() => {
        const sync = () => setSignedIn(IsTokenValid());
        // Re-check on mount too: the token may have changed between the initial render and here.
        sync();
        window.addEventListener('auth-changed', sync);
        window.addEventListener('storage', sync);
        return () => {
            window.removeEventListener('auth-changed', sync);
            window.removeEventListener('storage', sync);
        };
    }, []);

    return signedIn ? <Home /> : <Landing />;
}

export const Route = createFileRoute('/_auth/')({
    component: RootIndex,
});
